import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.DNhnOc72.js";const g=JSON.parse('{"title":"🎭 Módulo 07 — Ingeniería Social","description":"🎭 Módulo 07 — Ingeniería Social","frontmatter":{"title":"🎭 Módulo 07 — Ingeniería Social","description":"🎭 Módulo 07 — Ingeniería Social"},"headers":[],"relativePath":"modules/red-team/07-ingenieria-social.md","filePath":"modules/red-team/07-ingenieria-social.md","lastUpdated":1787319749000}'),o={name:"modules/red-team/07-ingenieria-social.md"};function n(d,e,s,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="🎭-modulo-07-—-ingenieria-social" tabindex="-1">🎭 Módulo 07 — Ingeniería Social <a class="header-anchor" href="#🎭-modulo-07-—-ingenieria-social" aria-label="Permalink to &quot;🎭 Módulo 07 — Ingeniería Social&quot;">​</a></h1><blockquote><p><strong>Nivel:</strong> Intermedio · <strong>Objetivo:</strong> entender, simular y defender contra ataques de ingeniería social (phishing, pretexting, vishing) de forma ética y controlada.</p></blockquote><p><a href="./.html"><img src="https://img.shields.io/badge/Nivel-Intermedio-orange?style=flat-square" alt="Nivel"></a><a href="./.html"><img src="https://img.shields.io/badge/Enfoque-Red%20Team-red?style=flat-square" alt="Enfoque"></a></p><hr><h2 id="📋-resumen" tabindex="-1">📋 Resumen <a class="header-anchor" href="#📋-resumen" aria-label="Permalink to &quot;📋 Resumen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atributo</th><th>Detalle</th></tr></thead><tbody><tr><td>🎯 <strong>Resultado</strong></td><td>Diseñar y ejecutar campañas de ingeniería social con autorización</td></tr><tr><td>🧪 <strong>Práctica</strong></td><td>GoPhish, SET, Evilginx2, pretexting, vishing</td></tr><tr><td>🗂️ <strong>Portafolio</strong></td><td>Campaña documentada con análisis de resultados</td></tr><tr><td>🔗 <strong>Requiere</strong></td><td><a href="./../02-pentesting-red-team/">Módulo 02 — Pentesting / Red Team</a></td></tr></tbody></table><hr><h2 id="🎯-objetivos-de-aprendizaje" tabindex="-1">🎯 Objetivos de aprendizaje <a class="header-anchor" href="#🎯-objetivos-de-aprendizaje" aria-label="Permalink to &quot;🎯 Objetivos de aprendizaje&quot;">​</a></h2><p>Al completar este módulo deberías ser capaz:</p><ul><li><strong>Phishing:</strong> crear campañas de phishing simulado con GoPhish y otras herramientas</li><li><strong>Pretexting:</strong> diseñar escenarios creíbles para obtener información o acceso</li><li><strong>Vishing:</strong> ejecutar ataques de ingeniería social por teléfono</li><li><strong>Landing pages:</strong> crear páginas falsas de login para capturar credenciales</li><li><strong>Defensa:</strong> implementar medidas técnicas y de proceso contra phishing</li><li><strong>Ética:</strong> entender y aplicar el marco ético de la ingeniería social</li></ul><hr><h2 id="🗂️-estructura-del-modulo" tabindex="-1">🗂️ Estructura del módulo <a class="header-anchor" href="#🗂️-estructura-del-modulo" aria-label="Permalink to &quot;🗂️ Estructura del módulo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Carpeta</th><th>Contenido</th><th>Estado</th></tr></thead><tbody><tr><td><a href="./herramientas/"><code>herramientas/</code></a></td><td>GoPhish, SET, Evilginx2 y más</td><td>✅ Completado</td></tr><tr><td><a href="./pretexting/"><code>pretexting/</code></a></td><td>Principios, pretextos y vishing</td><td>✅ Completado</td></tr><tr><td><a href="./phishing/"><code>phishing/</code></a></td><td>Landing pages, campañas y defensa</td><td>✅ Completado</td></tr></tbody></table><h3 id="📚-contenido-detallado" tabindex="-1">📚 Contenido detallado <a class="header-anchor" href="#📚-contenido-detallado" aria-label="Permalink to &quot;📚 Contenido detallado&quot;">​</a></h3><h4 id="_1-herramientas" tabindex="-1">1. Herramientas <a class="header-anchor" href="#_1-herramientas" aria-label="Permalink to &quot;1. Herramientas&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./herramientas/01-gophish.html"><code>01-gophish.md</code></a></td><td>Instalación, configuración y uso de GoPhish para campañas de phishing</td></tr><tr><td><a href="./herramientas/02-set-toolkit.html"><code>02-set-toolkit.md</code></a></td><td>Social Engineering Toolkit: credential harvester, website attacks, USB drops</td></tr><tr><td><a href="./herramientas/03-herramientas-fishing.html"><code>03-herramientas-fishing.md</code></a></td><td>King Phisher, Evilginx2, SocialFish, CredSniper y comparativa</td></tr></tbody></table><h4 id="_2-pretexting" tabindex="-1">2. Pretexting <a class="header-anchor" href="#_2-pretexting" aria-label="Permalink to &quot;2. Pretexting&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./pretexting/01-pretexting-principios.html"><code>01-pretexting-principios.md</code></a></td><td>Principios psicológicos, fases, componentes y marco ético</td></tr><tr><td><a href="./pretexting/02-pretextos-corporativos.html"><code>02-pretextos-corporativos.md</code></a></td><td>Scripts y escenarios por departamento (TI, RRHH, Finanzas, Ventas)</td></tr><tr><td><a href="./pretexting/03-vishing.html"><code>03-vishing.md</code></a></td><td>Vishing: técnicas, scripts, herramientas y ejemplos reales</td></tr></tbody></table><h4 id="_3-phishing" tabindex="-1">3. Phishing <a class="header-anchor" href="#_3-phishing" aria-label="Permalink to &quot;3. Phishing&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./phishing/01-landings-phishing.html"><code>01-landings-phishing.md</code></a></td><td>Templates de landing pages (Google, Microsoft, LinkedIn)</td></tr><tr><td><a href="./phishing/02-configuracion-gophish.html"><code>02-configuracion-gophish.md</code></a></td><td>Configuración paso a paso de campañas en GoPhish</td></tr><tr><td><a href="./phishing/03-medidas-defensa.html"><code>03-medidas-defensa.md</code></a></td><td>Defensa técnica, de proceso y de persona contra phishing</td></tr></tbody></table><hr><h2 id="🛠️-herramientas-principales" tabindex="-1">🛠️ Herramientas principales <a class="header-anchor" href="#🛠️-herramientas-principales" aria-label="Permalink to &quot;🛠️ Herramientas principales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Uso principal</th></tr></thead><tbody><tr><td><strong>GoPhish</strong></td><td>Campañas de phishing empresarial</td></tr><tr><td><strong>SET</strong></td><td>Phishing rápido, credential harvester, USB drops</td></tr><tr><td><strong>Evilginx2</strong></td><td>Bypass de MFA (Multi-Factor Authentication)</td></tr><tr><td><strong>King Phisher</strong></td><td>Campañas con análisis avanzado</td></tr><tr><td><strong>SocialFish</strong></td><td>Phishing de redes sociales</td></tr><tr><td><strong>CredSniper</strong></td><td>Captura de credenciales + MFA</td></tr></tbody></table><hr><h2 id="⚖️-aviso-etico" tabindex="-1">⚖️ Aviso ético <a class="header-anchor" href="#⚖️-aviso-etico" aria-label="Permalink to &quot;⚖️ Aviso ético&quot;">​</a></h2><p>La ingeniería social <strong>solo</strong> se practica con:</p><ul><li>✅ Autorización escrita explícita del responsable de seguridad</li><li>✅ Personal que ha consentido el ejercicio</li><li>✅ Entornos controlados y documentados</li><li>❌ Nada de suplantar identidades reales sin permiso</li><li>❌ Nada de atacar a terceros sin autorización</li><li>❌ Nada de usar la información para beneficio personal</li></ul><hr><h2 id="🔗-encaje-del-modulo-en-la-ruta" tabindex="-1">🔗 Encaje del módulo en la ruta <a class="header-anchor" href="#🔗-encaje-del-modulo-en-la-ruta" aria-label="Permalink to &quot;🔗 Encaje del módulo en la ruta&quot;">​</a></h2><p>Dentro de la <strong>Ruta 2 (Red Team)</strong>, este módulo complementa la <strong>Fase B</strong>:</p><ol><li><code>01-reconocimiento-osint/</code> ← Reconocimiento</li><li><code>02-pentesting-red-team/</code> ← Ciclo de pentest</li><li><code>03-analisis-vulnerabilidades/</code> ← Análisis</li><li><code>04-explotacion-web/</code> ← Explotación</li><li><code>05-post-explotacion/</code> ← Post-explotación</li><li><strong><code>07-ingenieria-social/</code></strong> ← <strong>Este módulo</strong> (complemento)</li></ol><hr><h2 id="✅-checkpoint" tabindex="-1">✅ Checkpoint <a class="header-anchor" href="#✅-checkpoint" aria-label="Permalink to &quot;✅ Checkpoint&quot;">​</a></h2><p>¿Puedes hacer lo siguiente sin guía?</p><ul><li>[ ] Crear una campaña de phishing con GoPhish</li><li>[ ] Diseñar un pretexto creíble para un departamento</li><li>[ ] Ejecutar un vishing y obtener credenciales</li><li>[ ] Crear una landing page que parezca legítima</li><li>[ ] Explicar las medidas de defensa contra phishing</li><li>[ ] Documentar una campaña con análisis de resultados</li></ul><p>Si todo es ✅, estás listo para el siguiente paso: <strong><a href="./../08-criptografia/">Módulo 08 — Criptografía</a></strong>.</p><hr><p><strong><a href="./../README.html">⬅ Volver a Ciberseguridad</a></strong> · <strong><a href="./../../RUTAS.html">🗺️ Ver Rutas</a></strong></p>',38)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
